    if ((minimum_margin == NULL) || (limiting_index == NULL) || 
        (momentum == NULL) || (reserve_vector == NULL)) {
        return ADCS_E_NULL;
    }

    *minimum_margin = INFINITY;
    *limiting_index = SIZE_MAX;
    *momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    *reserve_vector = (adcs_vec3_t){0.0, 0.0, 0.0};

    if ((wheels == NULL) || (speed_limits == NULL)) {
        return ADCS_E_RANGE;
    }

    if ((count < 1) || (count > 16)) {
        return ADCS_E_RANGE;
    }

    for (size_t i = 0; i < count; ++i) {
        if ((!isfinite(speed_limits[i])) || (speed_limits[i] <= 0.0)) {
            return ADCS_E_RANGE;
        }
        if ((!isfinite(wheels[i].inertia_kg_m2)) || (wheels[i].inertia_kg_m2 <= 0.0)) {
            return ADCS_E_RANGE;
        }
        if (!isfinite(wheels[i].speed_rad_s)) {
            return ADCS_E_RANGE;
        }
        double axis_norm = adcs_vec3_norm(&wheels[i].axis_body);
        if ((!isfinite(axis_norm)) || (axis_norm <= ADCS_EPS_NORM)) {
            return ADCS_E_RANGE;
        }
    }

    double current_min_margin = INFINITY;
    size_t current_limiting_index = SIZE_MAX;

    for (size_t i = 0; i < count; ++i) {
        double abs_speed = fabs(wheels[i].speed_rad_s);
        double margin = speed_limits[i] - abs_speed;

        if (margin < current_min_margin) {
            current_min_margin = margin;
            current_limiting_index = i;
        }
    }

    *minimum_margin = current_min_margin;
    *limiting_index = current_limiting_index;

    adcs_vec3_t acc_reserve = {0.0, 0.0, 0.0};
    adcs_vec3_t norm_axis;

    for (size_t i = 0; i < count; ++i) {
        if (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &norm_axis) != ADCS_OK) {
            return ADCS_E_DEGENERATE;
        }
        double margin = speed_limits[i] - fabs(wheels[i].speed_rad_s);
        double term_scalar = wheels[i].inertia_kg_m2 * margin;
        adcs_vec3_t term = adcs_vec3_scale(&norm_axis, term_scalar);
        acc_reserve = adcs_vec3_add(&acc_reserve, &term);
    }
    *reserve_vector = acc_reserve;

    adcs_status_t mom_status = adcs_wheel_momentum(wheels, count, momentum);
    if (mom_status != ADCS_OK) {
        return mom_status;
    }

    return ADCS_OK;
}

