        double limit = speed_limits[i];
        double inertia = wheels[i].inertia_kg_m2;
        double speed = wheels[i].speed_rad_s;
        adcs_vec3_t axis = wheels[i].axis_body;

        if (!isfinite(limit) || limit <= 0.0) {
            return ADCS_E_RANGE;
        }
        if (!isfinite(inertia) || inertia <= 0.0) {
            return ADCS_E_RANGE;
        }
        if (!isfinite(speed)) {
            return ADCS_E_RANGE;
        }

        double norm = adcs_vec3_norm(&axis);
        if (!isfinite(norm) || norm <= ADCS_EPS_NORM) {
            return ADCS_E_RANGE;
        }

