        if (margin < *minimum_margin) {
            *minimum_margin = margin;
            *limiting_index = i;
        }

        adcs_vec3_t axis_normed;
        axis_normed.x = axis.x / norm;
        axis_normed.y = axis.y / norm;
        axis_normed.z = axis.z / norm;

        adcs_vec3_t term = adcs_vec3_scale(&axis_normed, inertia * margin);
        *reserve_vector = adcs_vec3_add(reserve_vector, &term);
    }

    adcs_status_t status = adcs_wheel_momentum(wheels, count, momentum);
    if (status != ADCS_OK) {
        return status;
    }

    return ADCS_OK;
}

